from math import comb, erf, log, sqrt


def Phi(x):
    return 0.5 * (1 + erf(x / sqrt(2)))


def lr_binomial(k, n, p0, p1):
    """Likelihood ratio L(p1) / L(p0) for k wins in n trades."""
    return (p1 / p0) ** k * ((1 - p1) / (1 - p0)) ** (n - k)


def size_power(n, p0, p1, k_min):
    """Size and power of 'reject when k >= k_min', each rounded to 4 places."""
    def tail(p):
        return sum(comb(n, k) * p ** k * (1 - p) ** (n - k) for k in range(k_min, n + 1))
    return (round(tail(p0), 4), round(tail(p1), 4))


def lrt_poisson(xs, lam0):
    """-2 ln Lambda for a Poisson mean lam0, and its p-value on 1 degree of freedom."""
    n, total = len(xs), sum(xs)
    lam = total / n
    term = total * log(lam / lam0) if total > 0 else 0.0
    stat = 2 * (term - n * (lam - lam0))
    return (stat, 2 * (1 - Phi(sqrt(stat))))
